export const governanceGroups = ["Identity & Authority", "Evidence & Providers", "Runtime & Accountability", "Analysis & Institutional"] as const;

export type GovernanceGroup = (typeof governanceGroups)[number];
export type GovernanceVisualType = "identity" | "access" | "tier" | "capability" | "emergency" | "evidence" | "investigation-boundary" | "byok" | "provider-model" | "cost" | "workers" | "realtime" | "audit" | "admin" | "cross-lens" | "report" | "export-api" | "runtime-truth";
export type GovernanceLane = "request" | "check" | "decision" | "state" | "audit";
export type GovernanceNodeKind = "governed" | "allowed" | "human" | "denied" | "disabled" | "configuration";

export interface GovernanceControlNode {
  id: string;
  lane: GovernanceLane;
  kind: GovernanceNodeKind;
  label: string;
  state: string;
  evaluates: string[];
  results: string[];
  note: string;
}

export interface GovernanceDefinition {
  id: string;
  name: string;
  group: GovernanceGroup;
  subtitle: string;
  purpose: string;
  mechanism: string;
  controls: string[];
  decisions: string[];
  technicalFlow: string[];
  auditState: string[];
  boundary: string;
  limitation?: string;
  visualType: GovernanceVisualType;
  visualTitle: string;
  visualSummary: string;
  nodes: GovernanceControlNode[];
}

const node = (id: string, lane: GovernanceLane, kind: GovernanceNodeKind, label: string, state: string, evaluates: string[], results: string[], note: string): GovernanceControlNode => ({ id, lane, kind, label, state, evaluates, results, note });

