export type GovernanceId = (typeof governanceDefinitions)[number]["id"];
export const governanceIds = governanceDefinitions.map((item) => item.id);

export function governanceFromHash(): GovernanceDefinition {
  const hash = window.location.hash.slice(1);
  return governanceDefinitions.find((item) => item.id === hash) ?? governanceDefinitions[0];
}
